/**
 * @file Parses the JSON report written by RSpec.
 */

import { ParseOptions, TestParser } from '../../test-parser.js';
import {
  TestCaseError,
  TestCaseResult,
  TestExecutionResult,
  TestGroupResult,
  TestRunResult,
  TestSuiteResult,
} from '../../test-results.js';
import { RspecJson, RspecExample } from './rspec-json-types.js';

/**
 * Parser for JSON reports generated by the RSpec JSON formatter.
 */
export class RspecJsonParser implements TestParser {
  constructor(readonly options: ParseOptions) {}

  async parse(path: string, content: string): Promise<TestRunResult> {
    const mocha = this.getRspecJson(path, content);
    const result = this.getTestRunResult(path, mocha);
    result.sort(true);
    return result;
  }

  private getRspecJson(path: string, content: string): RspecJson {
    try {
      return JSON.parse(content);
    } catch (error) {
      throw new Error(`Invalid JSON at ${path}\n\n${error}`);
    }
  }

  private getTestRunResult(
    resultsPath: string,
    rspec: RspecJson,
  ): TestRunResult {
    const suitesMap: { [path: string]: TestSuiteResult } = {};

    const getSuite = (test: RspecExample): TestSuiteResult => {
      const path = test.file_path;
      return (
        suitesMap[path] ?? (suitesMap[path] = new TestSuiteResult(path, []))
      );
    };

    for (const test of rspec.examples) {
      const suite = getSuite(test);
      switch (test.status) {
        case 'failed': {
          this.processTest(suite, test, 'failed');

          break;
        }
        case 'passed': {
          this.processTest(suite, test, 'success');

          break;
        }
        case 'pending': {
          this.processTest(suite, test, 'skipped');

          break;
        }
        // No default
      }
    }

    const suites = Object.values(suitesMap);
    return new TestRunResult(resultsPath, suites, rspec.summary.duration);
  }

  private processTest(
    suite: TestSuiteResult,
    test: RspecExample,
    result: TestExecutionResult,
  ): void {
    const groupName =
      test.full_description === test.description
        ? null
        : test.full_description
            .slice(0, test.full_description.length - test.description.length)
            .trimEnd();

    let group = suite.groups.find((grp) => grp.name === groupName);
    if (group === undefined) {
      group = new TestGroupResult(groupName, []);
      suite.groups.push(group);
    }

    const error = this.getTestCaseError(test);
    const testCase = new TestCaseResult(
      test.full_description,
      result,
      test.run_time ?? 0,
      error,
    );
    group.tests.push(testCase);
  }

  private getTestCaseError(test: RspecExample): TestCaseError | undefined {
    const backtrace = test.exception?.backtrace;
    const message = test.exception?.message;
    if (backtrace === undefined) {
      return undefined;
    }

    let path;
    let line;
    const details = backtrace.join('\n');

    const src = this.getExceptionSource(backtrace);
    if (src) {
      path = src.path;
      line = src.line;
    }

    return {
      path,
      line,
      message,
      details,
    };
  }

  private getExceptionSource(
    backtrace: string[],
  ): { path: string; line: number } | undefined {
    const re = /^(.*?):(\d+):/;

    for (const str of backtrace) {
      const match = re.exec(str);
      if (match !== null) {
        const [, path, lineStr] = match;
        if (path.startsWith('./')) {
          const line = Number.parseInt(lineStr);
          return { path, line };
        }
      }
    }
    return undefined;
  }
}
